def tri(a='A', b='B', c='C'): return poly([a,b,c])

def step(prompt, text, reason, refs=()):
    return dict(prompt=prompt, explanation=text, justification=reason,
                theoryPoints=list(refs))

def phase(p, v, checks=(), labels=None, labelonly=()):
    return dict(points=p, view=v, checks=list(checks), labels=labels or {},labelOnly=list(labelonly))

def add(n, condition, answer, steps, phases, notes=(), cases=()):
    assert len(phases) == len(steps)+1, n
    model = dict(points={}, edges=[], planar=True, bounds=[0,0,100,70],
                 views={}, checks=[], labels={}, labelOffsets={}, labelOnly=[],
                 description='Чертёж к этой задаче. Дополнительные построения появляются по шагам; измерение на экране не заменяет доказательство.')
    rows = [('neutral', phases[0], 'Условие', None)]
    rows += [(f'step-{i}', p, f'Шаг {i}', None) for i,p in enumerate(phases[1:],1)]
    rows += [(f'case-{i}', p, label, unlock) for i,(p,label,unlock) in enumerate(cases,1)]
    for i,(key,p,label,unlock) in enumerate(rows):
        names = {k:f'{k}__v{i}' for k in p['points']}
        def rename(x):
            if isinstance(x,str): return names.get(x,x)
            if isinstance(x,list): return [rename(z) for z in x]
            if isinstance(x,dict): return {k:rename(v) for k,v in x.items()}
            return x
        normalized=normalize(p['points'],[p['view']])
        # normalize() uses screen-down y, whereas PlanarViewer projects math-up y.
        # Preserve authored/source orientation and fit the same geometry in a
        # shorter 100×70 frame; the 52-unit geometry extent stays unchanged.
        normalized={k:[v[0],75-v[1],0] for k,v in normalized.items()}
        model['points'].update({names[k]:v for k,v in normalized.items()})
        model['labels'].update({names[k]:p['labels'].get(k,k) for k in names if not k.startswith('_')})
        model['labelOnly'] += [names[k] for k in p.get('labelOnly',[])]
        view=rename(deepcopy(p['view']));view['label']=label
        if unlock is not None:view['availableFromStep']=unlock
        model['views'][key]=view
        model['checks']+=rename(p['checks'])
    CARDS.append(dict(number=n, part='single', printedPages=[214 if n<=834 else 215],
                      pdfPages=[215 if n<=834 else 216], condition=condition,
                      answer=answer, steps=steps, model=model, notes=list(notes),
                      sourceFigures=[274] if n==837 else []))

