p={'A':(0,0),'B':(4,.3),'C':(3,3),'D':(-1,2)};base826=phase(p,sc('ABCD',poly()))
def tilepatch(ms,ns):
    pts={};polygons=[];segments=[]
    u=[p['C'][i]-p['A'][i] for i in (0,1)];v=[p['D'][i]-p['B'][i] for i in (0,1)]
    for m in ms:
      for n in ns:
       for flipped in [False,True]:
        keys=[]
        for k,t in p.items():
          key=f'_{k}_{m}_{n}_{int(flipped)}';keys.append(key)
          t=[p['A'][i]+p['B'][i]-t[i] for i in (0,1)] if flipped else t
          pts[key]=[t[i]+m*u[i]+n*v[i] for i in (0,1)]
        polygons.append(keys);segments+=poly(keys)
    return phase(pts,sc([],segments,polygons=polygons))
