steps=[step('Что даёт равенство периметров двух верхних треугольников?', 'Пусть O — пересечение диагоналей. Из P(AOB)=P(BOC) после сокращения OB получаем AB+AO=BC+CO. Из P(AOD)=P(COD) получаем AD+AO=CD+CO.', 'Равенство периметров по условию.'),
 step('Предположи, что AO>CO. К чему это приводит?', 'Тогда AB<BC и AD<CD. Значит, B и D находятся со стороны A от серединного перпендикуляра к AC: каждая из этих точек ближе к A, чем к C. Весь отрезок BD лежит в той же открытой полуплоскости. Но O при AO>CO находится со стороны C — противоречие.', 'Серединный перпендикуляр разделяет точки, более близкие к разным концам отрезка; выпуклость полуплоскости.',[37,46]),
 step('Можно ли получить AO<CO?', 'Тем же рассуждением с перестановкой A и C исключаем AO<CO. Поэтому AO=CO. Повторяя доказательство для другой диагонали, получаем BO=DO.', 'Доказательство от противного; симметричное рассуждение.',[27]),
 step('Теперь сравни стороны четырёхугольника.', 'Из AB+AO=BC+CO следует AB=BC. В остальных равенствах периметров одинаковые половины диагоналей также сокращаются: BC=CD=DA. Все четыре стороны равны; это ромб.', 'Определение ромба; признак параллелограмма по диагоналям.',[49,52])]
add(831,'Диагонали выпуклого четырёхугольника делят его на четыре треугольника с равными периметрами. Докажите, что четырёхугольник — ромб.',
 'Диагонали делятся пополам, а все четыре стороны равны.',steps,repeat(b,5),notes=['Чертёж показывает допустимый пример, но вывод о ромбе доказывается из равенств периметров, а не из внешнего вида.'])

p={'A':(0,4),'B':(-4,0),'C':(5,0),'M':(-2,2),'N':(2.5,2)}
b=phase({'A':p['A'],'_left':p['B'],'_right':p['C'],'L':(3.5,.5)},
        sc('AL',lines=[['_left','_right']]),labels={'L':'l'},labelonly=['L'])
v=phase(p,sc(p,[['A','B'],['A','C']],lines=[['B','C'],['M','N']]),[equal(('A','M'),('M','B')),equal(('A','N'),('N','C')),par('B','C','M','N')])
steps=[step('Построй два примера середин.', 'Возьмём разные точки B и C данной прямой l. Пусть M и N — середины AB и AC. По теореме о средней линии MN параллельна BC.', 'Средняя линия треугольника.',[69]),
 step('Почему любая искомая середина лежит на MN?', 'Для произвольной точки X на l середина AX вместе с M образует среднюю линию треугольника ABX. Поэтому она лежит на прямой через M, параллельной l, то есть на MN. При X=B это сама M.', 'Единственность параллельной прямой; средняя линия.',[28,69]),
 step('Докажи обратное: подходит ли каждая точка Y этой прямой?', 'Для любой Y на MN прямая AY пересекает l в точке X. Она не параллельна l, поскольку A не лежит на MN. В треугольнике ABX прямая MY параллельна BX и проходит через середину AB, поэтому Y — середина AX. Для Y=M берём X=B.', 'Обратное следствие теоремы о средней линии.',[66,69]),
 step('Сформулируй ответ полностью.', 'Искомое множество — вся прямая, параллельная l и проходящая через середину любого отрезка от A до l. Она находится посередине между A и l. Проверены оба включения.', 'Найдено множество всех и только подходящих точек.',[38])]
add(832,'Найдите множество середин всех отрезков, соединяющих данную точку A со всеми точками прямой l, не проходящей через A.',
 'Вся прямая, параллельная l и проходящая через середину перпендикуляра из A на l.',steps,[b,v,v,v,v])

p=trap(8,4,3);p.update(M=mid(p['A'],p['D']),N=mid(p['B'],p['C']))
b=phase(p,sc(p,poly(),lines=[['M','N']],equalSegments=[eq('A','M'),eq('M','D'),eq('B','N',2),eq('N','C',2)]),
    [equal(('A','B'),('C','D')),perp('M','N','A','D'),par('A','D','B','C')])
steps=[step('Что известно о симметрии равнобедренной трапеции?', 'Опустим перпендикуляры из концов меньшего основания на большее. Прямоугольные треугольники у краёв равны по гипотенузе и катету: боковые стороны равны, а высоты между параллельными основаниями одинаковы. Поэтому свесы большего основания равны.', 'Признак равенства прямоугольных треугольников; расстояние между параллельными прямыми.',[35,38,50]),
 step('Где находятся середины оснований?', 'Равные свесы означают, что середины M и N оснований находятся на одном перпендикуляре к основаниям. Поэтому MN перпендикулярна обоим основаниям.', 'Середины двух параллельных отрезков с равными свесами.',[50]),
 step('Сформулируй обратное утверждение.', 'Если прямая через середины оснований трапеции перпендикулярна основаниям, то трапеция равнобедренная. Важно сохранить условие, что исходная фигура — трапеция.', 'В обратном утверждении меняем местами условие и заключение.',[27,50]),
 step('Докажи обратное.', 'При отражении относительно MN концы каждого основания меняются местами: M и N — их середины, а MN — серединный перпендикуляр. Поэтому боковая сторона AB переходит в DC. Отражение сохраняет длину, значит, AB=DC.', 'Свойство серединного перпендикуляра и равенство зеркальных прямоугольных треугольников.',[35,37])]
add(833,'Докажите, что прямая через середины оснований равнобедренной трапеции перпендикулярна основаниям. Сформулируйте и докажите обратное утверждение.',
 'Обратно: трапеция с перпендикуляром через середины оснований равнобедренная.',steps,repeat(b,5))

p=rect(6,4);p.update(P=(2,2),Q=(3,3),R=(4,2),S=(3,1))
v=sc(p,poly(),rays=[['A','Q'],['B','S'],['C','S'],['D','Q']])
b=phase(p,v,[equal(('P','Q'),('Q','R'),('R','S'),('S','P')),perp('P','Q','Q','R')])
