square=rect(4,4);square['O']=(2,2)
sq=phase(square,sc(square,poly(),rays=[['A','O'],['B','O'],['C','O'],['D','O']]))
steps=[step('Какие углы образуют соседние биссектрисы?', 'Углы прямоугольника равны 90°, поэтому каждая биссектриса образует со сторонами углы 45°. Биссектрисы соседних углов перпендикулярны, а противоположных — параллельны. Получившийся четырёхугольник является прямоугольником.', 'Биссектриса; признаки параллельности и перпендикулярности.',[17,24,51]),
 step('Почему его соседние стороны равны?', 'Прямая через середины двух противоположных сторон исходного прямоугольника является его осью симметрии. Она меняет местами две противоположные вершины нового четырёхугольника, а две другие оставляет на месте. Поэтому эта ось содержит его диагональ и делит угол при её конце пополам.', 'Симметрия пар исходных биссектрис; равенство соответствующих углов.'),
 step('Используй полученные углы.', 'Диагональ нового прямоугольника делит прямой угол на два угла по 45°. В образовавшемся прямоугольном треугольнике острые углы равны, значит, равны и катеты — соседние стороны прямоугольника. Получен квадрат.', 'Равные углы треугольника лежат против равных сторон; определение квадрата.',[32,52]),
 step('Всегда ли образуется четырёхугольник?', 'Если исходный прямоугольник сам является квадратом, все четыре биссектрисы пересекаются в центре. Четырёхугольник не образуется. В условии уже сказано, что он образовался, поэтому этот вырожденный случай исключён.', 'Проверка предпосылки задачи; диагонали квадрата.',[52])]
add(834,'Биссектрисы всех углов прямоугольника при пересечении образовали четырёхугольник. Докажите, что он — квадрат.',
 'Получившийся невырожденный четырёхугольник — квадрат.',steps,[b,b,v2,v2,v2],
    notes=['Когда исходный прямоугольник — квадрат, четырёхугольника нет; не подменять этот случай «квадратом нулевой стороны».'],cases=[(sq,'Исходный квадрат: только одна точка пересечения',4)])

def outer_square(p,a,b,side=-1):
    u=[p[b][i]-p[a][i] for i in (0,1)];w=[-side*u[1],side*u[0]]
    return [[p[b][i]+w[i] for i in (0,1)],[p[a][i]+w[i] for i in (0,1)]]

p={'A':(0,0),'B':(5,0),'C':(7,3),'D':(2,3)};squares=[]
for i,(a,b0) in enumerate(poly()):
    c,d=outer_square(p,a,b0);p[f'_c{i}']=c;p[f'_d{i}']=d
    squares.append([a,b0,f'_c{i}',f'_d{i}']);p['KLMN'[i]]=mid(p[a],c)
v=sc('ABCDKLMN',sum([poly(s) for s in squares],[]))
b=phase(p,v)
focus=phase({k:p[k] for k in ['B','C','K','L','M']},sc('BCKLM',tri('K','B','L')+tri('L','C','M')), [equal(('K','B'),('M','C')),equal(('L','B'),('L','C'))])
final=phase(p,more(v,segs=poly('KLMN'),highlightSegments=poly('KLMN')),
    [equal(('K','L'),('L','M'),('M','N'),('N','K')),perp('K','L','L','M')])
steps=[step('Назови центры квадратов по порядку.', 'Пусть K,L,M,N — центры квадратов на AB,BC,CD,DA. Центральная симметрия относительно центра параллелограмма переводит квадрат на AB в квадрат на CD, а квадрат на BC — в квадрат на DA. Значит, K и M, L и N попарно симметричны, и KLMN — параллелограмм.', 'Центральная симметрия; диагонали делятся пополам.',[49,53]),
 step('Сравни треугольники KBL и MCL.', 'BK=CM, поскольку внешние квадраты на равных AB и CD равны. BL=CL — половины диагоналей одного квадрата. При B и C каждая диагональ квадрата составляет 45° со стороной; AB параллельна CD. Поэтому углы KBL и MCL равны. Треугольники равны по двум сторонам и углу между ними.', 'Свойства квадрата и первый признак равенства.',[15,48,52]),
 step('Почему отрезки LK и LM перпендикулярны?', 'Поворот на 90° вокруг L, совмещающий C с B, совмещает также луч CM с лучом BK: направления диагоналей внешних квадратов отличаются на 90°. Поскольку CM=BK, точка M при этом попадает в K. Значит, LM и LK равны и образуют прямой угол.', 'Поворот сохраняет расстояния; это также следует из равных треугольников предыдущего шага.'),
 step('Какой это параллелограмм?', 'У параллелограмма KLMN есть прямой угол и равные соседние стороны. Следовательно, это квадрат.', 'Признаки прямоугольника и ромба; определение квадрата.',[51,52])]
add(835,'На всех сторонах параллелограмма вне него построены квадраты. Докажите, что точки пересечения диагоналей этих квадратов являются вершинами квадрата.',
 'Центры внешних квадратов образуют квадрат.',steps,[b,b,focus,focus,final],notes=['Поворот на 90° используется как наглядное совмещение двух уже доказанно равных треугольников, а не как неразъяснённая ссылка на главу о движениях.'])

p=rect(4,4);p['M']=(4,1.5);r=math.hypot(4,1.5);k=r-1.5;p['K']=(k,4)
b=phase(p,sc(p,poly()+[['A','M'],['A','K']],angleArcs=[arc('A','B','K',1),arc('A','K','M',1)]),
    [col('C','M','D'),col('B','K','C'),equal(('A','B'),('B','C'),('C','D'),('D','A'))])
q={**p,'E':(4,-k)}
v=phase(q,sc(q,poly()+[['A','M'],['A','K'],['A','E'],['D','E']],equalSegments=[eq('B','K'),eq('D','E')]),[equal(('A','M'),('E','M')),equal(('B','K'),('D','E'))])
steps=[step('Добавь отрезок, равный BK.', 'На продолжении CD за D отложим DE=BK. Прямоугольные треугольники ABK и ADE равны по двум катетам: AB=AD, BK=DE. Обозначим ∠BAK=∠DAE=α.', 'Равенство прямоугольных треугольников.',[35,52]),
 step('Воспользуйся биссектрисой.', 'Так как AK — биссектриса BAM, угол BAM равен 2α. Следовательно, ∠MAD=90°−2α и ∠MAE=90°−α.', 'Биссектриса и прямой угол BAD.',[17]),
 step('Найди второй угол треугольника AME.', 'В прямоугольном ADE угол AED равен 90°−α. Лучи EM и ED совпадают, поэтому ∠AEM=90°−α. В треугольнике AME углы при A и E равны; значит, AM=EM.', 'Сумма углов треугольника; равным углам противолежат равные стороны.',[31,32]),
 step('Разложи EM на два отрезка.', 'EM=ED+DM=BK+DM. Поэтому AM=BK+DM. При M=D равенство даёт 4=4+0 на нашем примере; общий вывод сохраняется. При M=C получается AM=BK+DC.', 'Сложение длин последовательных отрезков.')]
add(836,'На стороне CD квадрата ABCD отмечена точка M. Биссектриса угла BAM пересекает BC в K. Докажите: AM=BK+DM.',
 'AM=BK+DM.',steps,[b,v,v,v,v],notes=['Положение M в концах стороны допускается как отдельный предельный случай; основной рисунок — внутренняя точка.'])

p={'A':(0,0),'B':(1,1),'C':(2,1),'D':(3,1),'E':(3,0),'_L':(0,1),'_U':(1,0),'_V':(2,0)}
edges=[['A','E'],['_L','D'],['A','_L'],['_U','B'],['_V','C'],['E','D'],['A','B'],['A','C'],['A','D']]
