steps=[step('Что известно про первый угол?', 'Три квадрата рисунка 274 равны и стоят в ряд. Пусть их сторона равна 1. AB — диагональ первого квадрата, поэтому ∠BAE=45°.', 'Свойство диагонали квадрата.',[52]),
 step('Отрази D относительно AE.', 'Получим F: EF=ED=1, а AF зеркально симметричен AD. Значит, ∠FAE=∠DAE. У отрезка AC горизонтальный и вертикальный переходы равны 2 и 1; у CF — 1 и 2 вниз.', 'Равенство зеркальных прямоугольных треугольников.'),
 step('Каким оказался треугольник ACF?', 'Прямоугольные треугольники с катетами 2 и 1 равны. При перестановке катетов направления AC и CF перпендикулярны, а их длины равны. Поэтому ACF — равнобедренный прямоугольный треугольник и ∠CAF=45°.', 'Равенство по двум катетам; сумма острых углов 90°.',[35,31]),
 step('Собери сумму трёх углов.', '∠CAE+∠DAE=∠CAE+∠FAE=∠CAF=45°. Добавим ∠BAE=45°: искомая сумма равна 90°.', 'Сложение углов по обе стороны луча AE.')]
add(837,'На рисунке 274 три квадрата стоят в ряд: A — нижняя левая вершина, E — нижняя правая, B,C,D — верхние правые вершины первого, второго и третьего квадратов. Найдите ∠BAE+∠CAE+∠DAE.',
 '90°.',steps,[b,b,v,v,v],notes=['Положение букв и число квадратов сверены непосредственно с рисунком 274.'])

p=rect(4,4);p['M']=(2*math.sqrt(3),2)
b=phase(p,sc(p,poly()+[['A','M'],['C','M']],angleArcs=[arc('A','M','B'),arc('C','M','D')]),[ang('M','A','B',60),ang('M','C','D',15)])
q=deepcopy(p);q['N']=q.pop('M')
v=phase(q,sc(q,poly()+[['A','N'],['B','N'],['C','N']],equalSegments=[eq('A','B'),eq('A','N'),eq('B','N')]),
    [equal(('A','B'),('A','N'),('B','N')),ang('N','C','D',15),ang('N','B','C',30)])
steps=[step('Построй вспомогательный равносторонний треугольник.', 'На AB внутрь квадрата построим равносторонний ABN. Тогда ∠NAB=∠ABN=60°, а BN=AB=BC. Поэтому ∠NBC=90°−60°=30°.', 'Равносторонний треугольник и прямой угол ABC.',[31,52]),
 step('Какой угол получится при C?', 'В равнобедренном BNC угол при B равен 30°. Углы при N и C равны (180°−30°)/2=75°. Поэтому ∠NCD=90°−75°=15°.', 'Углы равнобедренного треугольника.',[18,31]),
 step('Почему N совпадает с данной точкой M?', 'Внутри квадрата условие ∠MAB=60° задаёт единственный луч из A, а ∠MCD=15° — единственный луч из C. N лежит на обоих лучах. Их пересечение единственно, следовательно, M=N.', 'Две различные прямые имеют не более одной общей точки.',[1]),
 step('Запиши искомый угол.', '∠MBC=∠NBC=30°.', 'Совпадение M и N.')]
add(838,'Внутри квадрата ABCD точка M выбрана так, что ∠MAB=60°, ∠MCD=15°. Найдите ∠MBC.',
 '30°.',steps,[b,v,v,v,b])

def task839(a=5,u=2,v=3):
    return dict(A=(u,v),B=(0,0),C=(a,0),D=(a,-a),E=(0,-a),
        T=(a+v,a-u),M=(u+v,v+a-u),H=(u-v,u+v),K=(-v,u),
        Q=(a+v,-u),P=(-v,u-a))
p=task839();squares=[poly('BCDE'),poly('ACTM'),poly('BAHK')]
b=phase(p,sc(p,sum(squares,[])+poly('TCDQ')+poly('EBKP')),
    [par('T','C','Q','D'),par('C','D','T','Q'),par('E','B','P','K'),par('B','K','E','P')])
focus=phase({k:p[k] for k in 'APQ'},sc('APQ',tri('A','P','Q')),
    [equal(('A','P'),('A','Q')),perp('A','P','A','Q')])
ob=task839(u=-1,v=3);obtuse=phase(ob,sc(ob,sum(squares,[])+poly('TCDQ')+poly('EBKP')+tri('A','P','Q')),
    [equal(('A','P'),('A','Q')),perp('A','P','A','Q')])
steps=[step('Выбери удобные координаты и объясни обозначения.', 'Расположим BC горизонтально: B=(0;0), C=(a;0), A=(u;v), где a>0, v>0. Число u может быть любым: основание перпендикуляра из A не обязано лежать на BC. Пара (x;y) обозначает горизонтальное и вертикальное расстояния со знаком.', 'Вспомогательный координатный способ: перенос и поворот всего рисунка не меняют равенство длин и углов.'),
 step('Найди внешние вершины нужных квадратов.', 'У квадрата BCDE: D=(a;−a), E=(0;−a). Для квадрата ACTM получаем T=(a+v;a−u). Для квадрата BAHK получаем K=(−v;u). При повороте отрезка на 90° горизонтальный и вертикальный переходы меняются местами, один меняет знак.', 'У квадрата соседние стороны равны и перпендикулярны; все три квадрата построены наружу.',[52]),
 step('Используй два параллелограмма.', 'В TCDQ переход от T к Q такой же, как от C к D; поэтому Q=(a+v;−u). В EBKP переход от E к P такой же, как от B к K; поэтому P=(−v;u−a).', 'Противоположные стороны параллелограмма равны и параллельны.',[48]),
 step('Сравни переходы от A к Q и от A к P.', 'Пусть x=a+v−u и y=−u−v. Тогда от A к Q переход равен (x;y), а от A к P — (y;−x). Эти два перехода отличаются поворотом на 90°, имеют одинаковую длину и перпендикулярны. Они не нулевые: при x=y=0 получилось бы a+2v=0, что невозможно.', 'Равенство прямоугольных треугольников при перестановке катетов; проверка невырожденности.',[35]),
 step('Сформулируй вывод.', 'AP=AQ и ∠PAQ=90°. Поэтому APQ — равнобедренный прямоугольный треугольник. Рассуждение сохраняется и для тупоугольного исходного ABC.', 'Определение равнобедренного прямоугольного треугольника.')]
add(839,'Снаружи треугольника ABC построены квадраты BCDE, ACTM, BAHK, затем параллелограммы TCDQ и EBKP. Докажите, что APQ — прямоугольный равнобедренный треугольник.',
 'AP=AQ, ∠PAQ=90°.',steps,[b,b,b,b,focus,focus],
    notes=['Авторский координатный способ полностью объяснён; до публикации желателен дополнительный синтетический разбор без материала 9 класса.'],
    cases=[(obtuse,'Основание высоты вне BC',5)])

a,b0,h=8,4,3;d=math.hypot((a+b0)/2,h)
data={'U':(0,4),'V':(a,4),'W':(0,2),'X':(b0,2),'Y':(0,0),'Z':(d,0)}
initial=phase(data,sc(data,[['U','V'],['W','X'],['Y','Z']]))
p=trap(a,b0,h);p.update(X=((a+b0)/2,0),G=(d,0),M=(a/2,0))
circlep={**p,'_up':((a+b0)/2,6)}
line=phase({k:circlep[k] for k in ['A','D','X','_up']},sc('ADX',[['A','D']],lines=[['X','_up']]))
circleview=phase(circlep,sc('ADCX',[['A','D'],['A','C']],lines=[['X','_up']],circles=[dict(center='A',through='G')]),[perp('X','C','A','D'),equal(('A','C'),('A','G'))])
final=phase(p,sc('ABCDX',poly()+[['A','C']],dashSegments=[['C','X']]),[equal(('A','B'),('C','D')),par('A','D','B','C')])
steps=[step('Когда построение возможно?', 'Обозначим большее основание a, меньшее b: a>b>0. В равнобедренной трапеции горизонтальная проекция диагонали равна (a+b)/2. Поэтому диагональ d должна быть строго больше (a+b)/2. При равенстве высота равна нулю; при меньшем d решения нет.', 'Равные свесы оснований; гипотенуза больше катета.',[50,34]),
 step('Построй основание и проекцию диагонали.', 'Построим AD=a. На AD отметим X так, что AX=(a+b)/2; эту длину получаем сложением данных отрезков и делением пополам. Через X проведём перпендикуляр к AD.', 'Построение середины отрезка и перпендикуляра.',[23]),
 step('Найди конец диагонали.', 'Окружность с центром A и радиусом d пересекает этот перпендикуляр в двух точках. Возьмём C в выбранной полуплоскости относительно AD. Тогда AC=d. Второй выбор даст зеркальную трапецию.', 'Расстояние от A до перпендикуляра равно AX<d, поэтому пересечений два.',[76]),
 step('Закончи трапецию.', 'Через C проведём прямую, параллельную AD, и отложим CB=b в сторону A. Тогда проекция B на AD находится на расстоянии (a−b)/2 от A. Свес справа также (a−b)/2. Высоты равны, значит, боковые стороны AB и CD равны.', 'Равенство прямоугольных треугольников по двум катетам.',[35,50]),
 step('Проверь данные и число решений.', 'AD=a, BC=b, AC=d; основания параллельны и боковые стороны равны. При a>b>0 и d>(a+b)/2 решение единственно с точностью до движения и отражения. При равных основаниях получился бы прямоугольник, а не трапеция в определении этого учебника.', 'Проверка всех условий и определения трапеции.',[50])]
add(840,'Постройте равнобедренную трапецию по двум основаниям и диагонали. На исходном чертеже UV=a, WX=b, YZ=d.',
 'При a>b>0 построение возможно тогда и только тогда, когда d>(a+b)/2.',steps,[initial,initial,line,circleview,final,final],notes=['На начальном рисунке UV=a, WX=b, YZ=d.'])

p={'A':(0,4*math.sqrt(3)),'B':(-4,0),'C':(4,0)};p.update(M=mid(p['B'],p['C']),N=mid(p['A'],p['C']))
