steps=[step('Как ось симметрии действует на вершины?', 'Отражение переводит множество из трёх вершин в себя. Хотя бы одна вершина остаётся на месте: остальные вершины могут только меняться попарно. Все три на оси лежать не могут, иначе треугольник вырожден. Поэтому на каждой оси лежит ровно одна вершина, а две другие меняются местами.', 'Отражение имеет неподвижные точки только на оси; три вершины неколлинеарны.'),
 step('Какие стороны равны при одной оси?', 'Если ось проходит через A и меняет B с C, отражение совмещает AB с AC. Значит, AB=AC. Такая ось является серединным перпендикуляром к BC, то есть для данной вершины она единственна.', 'Расстояния до зеркальных точек равны; единственность серединного перпендикуляра.',[37]),
 step('Через какую вершину проходит другая ось?', 'Другая ось не может проходить через ту же A. Пусть она проходит через B. Тогда она меняет местами A и C, поэтому BA=BC.', 'Две разные оси не могут быть одним серединным перпендикуляром.',[37]),
 step('Соедини два равенства.', 'Имеем AB=AC и AB=BC. Следовательно, AB=BC=CA: треугольник равносторонний.', 'Определение равностороннего треугольника.',[18])]
add(841,'Докажите: если треугольник имеет более одной оси симметрии, он равносторонний.',
 'Две разные оси симметрии дают равенство всех трёх сторон.',steps,repeat(b,5))

